path = "nodes/34aaa432.txt"
chain = []
while True:
    r = await yuki_workspace_read({"path": path})
    text = r["data"]["text"]
    d = {}
    for line in text.strip().splitlines():
        if "=" in line:
            k, v = line.split("=", 1)
            d[k.strip()] = v.strip()
    val = int(d["value"])
    chain.append((path, val))
    if val % 2 == 0:
        nxt = d.get("left")
    else:
        nxt = d.get("right")
    if nxt is None or nxt == "END":
        break
    path = nxt
